import Fastify from "fastify";

export const app = Fastify({ logger: false });

async function catalog(fastify) {
  fastify.addHook("onRequest", async function authenticate(request) {
    request.user = { role: "admin" };
  });
}

app.register(catalog);

app.get("/products", async function list() {
  return [{ id: "notebook", name: "Notebook", price: 4.5 }];
});
